            return results;
        }

        List<String> normalizedEmails = new List<String>();
        for (Request request : requests) {
            String email = null;
            if (request != null) {
                email = request.email;
            }
            normalizedEmails.add(normalizeEmail(email));
            results.add(new Result());
        }

        Set<String> uniqueEmails = new Set<String>();
        List<String> emailsToQuery = new List<String>();
        for (String normalizedEmail : normalizedEmails) {
            if (normalizedEmail != null && !uniqueEmails.contains(normalizedEmail)) {
                uniqueEmails.add(normalizedEmail);
                emailsToQuery.add(normalizedEmail);
            }
        }

        Map<String, Contact> earliestContactByEmail = new Map<String, Contact>();
        if (!emailsToQuery.isEmpty()) {
            List<Contact> contacts = [SELECT Id, Email, CreatedDate FROM Contact WHERE LOWER(Email) IN :emailsToQuery ORDER BY CreatedDate ASC];
            for (Contact contact : contacts) {
                String contactEmail = normalizeEmail(contact.Email);
                if (contactEmail == null) {
                    continue;
