public class OrderPayloadParser {
    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total = 0;
    }

    public class PayloadException extends Exception {
        public PayloadException(String message) {
            super(message);
        }
    }

    public static Order parse(String body) {
        try {
            if (body == null || body.trim().length() == 0) {
                throw new PayloadException('Payload body is required.');
            }

            Object rootObj;
            try {
                rootObj = JSON.deserializeUntyped(body);
            } catch (Exception e) {
                throw new PayloadException('Payload body is not valid JSON.');
            }

            if (rootObj == null || !(rootObj instanceof Map)) {
                throw new PayloadException('Payload body must be a JSON object.');
            }

            Map<String, Object> root = (Map<String, Object>) rootObj;
            Order order = new Order();
            order.orderNumber = getRequiredString(root.get('number'), 'number');
            order.orderDate = parseDate(root.get('date'));
            order.currencyCode = getOptionalString(root.get('currency'));
            order.customerEmail = parseCustomerEmail(root.get('customer'));
            order.lines = parseLines(root.get('lines'));

            Decimal total = 0;
            for (Line line : order.lines) {
                total = total + line.lineTotal;
            }
            order.total = total.setScale(2, RoundingMode.HALF_UP);

            return order;
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Invalid payload.');
        }
    }

    public static String toAcknowledgement(Order order) {
        try {
            Integer lineCount = (order != null && order.lines != null) ? order.lines.size() : 0;
            Decimal total = (order != null && order.total != null) ? order.total : 0;
            String number = (order != null) ? order.orderNumber : null;

            return '{"number":' + JSON.serialize(number) +
                   ',"status":"RECEIVED",' +
                   '"lineCount":' + lineCount +
                   ',"total":' + JSON.serialize(total) + '}';
        } catch (PayloadException e) {
            throw e;
        } catch (Exception e) {
            throw new PayloadException('Invalid order for acknowledgement.');
        }
    }

    private static List<Line> parseLines(Object linesObj) {
        List<Line> lines = new List<Line>();
        if (linesObj == null || !(linesObj instanceof List)) {
            return lines;
        }

        List<Object> elements = (List<Object>) linesObj;
        for (Object element : elements) {
            if (element == null || !(element instanceof Map)) {
                throw new PayloadException('Each line must be a JSON object.');
            }

            Map<String, Object> lineMap = (Map<String, Object>) element;
            Line line = new Line();
            line.sku = getRequiredString(lineMap.get('sku'), 'lines[].sku');
            line.quantity = getRequiredPositiveInteger(lineMap.get('quantity'), 'lines[].quantity');
            line.unitPrice = getRequiredNonNegativeDecimal(lineMap.get('unitPrice'), 'lines[].unitPrice');
            line.discount = getOptionalDecimal(lineMap.get('discount'));
            if (line.discount == null) {
                line.discount = 0;
            }

            line.lineTotal = roundHalfUpToTwoDecimals(line.quantity * line.unitPrice * (1 - line.discount));
            lines.add(line);
        }

        return lines;
    }

    private static String parseCustomerEmail(Object customerObj) {
        if (customerObj == null || !(customerObj instanceof Map)) {
            return null;
        }

        Map<String, Object> customer = (Map<String, Object>) customerObj;
        return getOptionalString(customer.get('email'));
    }

    private static Date parseDate(Object dateObj) {
        if (dateObj == null) {
            return null;
        }

        String dateText = getOptionalString(dateObj);
        if (dateText == null || dateText.trim().length() == 0) {
            return null;
        }

        dateText = dateText.trim();
        if (!dateText.matches('^\\d{4}-\\d{2}-\\d{2}$')) {
            return null;
        }

        try {
            return Date.valueOf(dateText);
        } catch (Exception e) {
            return null;
        }
    }

    private static String getRequiredString(Object value, String field) {
        if (value == null) {
            throw new PayloadException(field + ' is required.');
        }

        if (value instanceof Map || value instanceof List) {
            throw new PayloadException(field + ' must be a scalar value.');
        }

        String result = String.valueOf(value);
        if (result.trim().length() == 0) {
            throw new PayloadException(field + ' is blank.');
        }

        return result;
    }

    private static String getOptionalString(Object value) {
        if (value == null) {
            return null;
        }

        if (value instanceof Map || value instanceof List) {
            return null;
        }

        return String.valueOf(value);
    }

    private static Integer getRequiredPositiveInteger(Object value, String field) {
        if (value == null) {
            throw new PayloadException(field + ' is required.');
        }

        Integer intValue = toInteger(value);
        if (intValue == null || intValue <= 0) {
            throw new PayloadException(field + ' must be a positive integer.');
        }

        return intValue;
    }

    private static Decimal getRequiredNonNegativeDecimal(Object value, String field) {
        if (value == null) {
            throw new PayloadException(field + ' is required.');
        }

        Decimal dec = toDecimal(value);
        if (dec == null || dec < 0) {
            throw new PayloadException(field + ' must be a non-negative decimal.');
        }

        return dec;
    }

    private static Decimal getOptionalDecimal(Object value) {
        if (value == null) {
            return null;
        }

        return toDecimal(value);
    }

    private static Integer toInteger(Object value) {
        if (value == null) {
            return null;
        }

        if (value instanceof Integer) {
            return (Integer) value;
        }

        Decimal dec = toDecimal(value);
        if (dec == null) {
            return null;
        }

        try {
            Decimal integral = dec.setScale(0, RoundingMode.FLOOR);
            if (dec != integral) {
                return null;
            }
            return dec.intValue();
        } catch (Exception e) {
            return null;
        }
    }

    private static Decimal toDecimal(Object value) {
        if (value == null) {
            return null;
        }

        if (value instanceof Decimal) {
            return (Decimal) value;
        }

        if (value instanceof Map || value instanceof List) {
            return null;
        }

        try {
            return Decimal.valueOf(String.valueOf(value));
        } catch (Exception e) {
            return null;
        }
    }

    private static Decimal roundHalfUpToTwoDecimals(Decimal value) {
        if (value == null) {
            return 0;
        }

        return value.setScale(2, RoundingMode.HALF_UP);
    }
}
