public with sharing class LeadImportService {
    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            successCount = 0;
            insertedIds = new List<Id>();
            errorsByIndex = new Map<Integer, String>();
        }
    }

    public static LeadImportService.ImportResult importLeads(List<Lead> leads) {
        LeadImportService.ImportResult result = new LeadImportService.ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> candidates = new List<Lead>();
        List<Integer> candidateToInputIndex = new List<Integer>();
        Map<String, Integer> firstSeenByEmail = new Map<String, Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads.get(i);

            if (lead == null) {
                result.errorsByIndex.put(i, 'Lead is null.');
                continue;
            }

            String emailKey = getNormalizedEmail(lead.Email);

            if (emailKey != null) {
                if (firstSeenByEmail.containsKey(emailKey)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + emailKey);
                    continue;
                }
                firstSeenByEmail.put(emailKey, i);
            }

            if (lead.LeadSource == null || lead.LeadSource.trim() == '') {
                lead.LeadSource = 'Web';
            }

            candidates.add(lead);
            candidateToInputIndex.add(i);
        }

        if (!candidates.isEmpty()) {
            List<Database.SaveResult> saveResults;

            try {
                saveResults = Database.insert(candidates, Database.AllOrNoneType.None);
            } catch (DmlException dmlException) {
                for (Integer candidateIndex = 0; candidateIndex < candidateToInputIndex.size(); candidateIndex++) {
                    Integer inputIndex = candidateToInputIndex.get(candidateIndex);
                    if (!result.errorsByIndex.containsKey(inputIndex)) {
                        result.errorsByIndex.put(inputIndex, dmlException.getMessage());
                    }
                }
                return result;
            }

            Integer resultCount = Math.min(saveResults.size(), candidateToInputIndex.size());

            for (Integer candidateIndex = 0; candidateIndex < resultCount; candidateIndex++) {
                Database.SaveResult saveResult = saveResults.get(candidateIndex);
                Integer inputIndex = candidateToInputIndex.get(candidateIndex);

                if (saveResult.isSuccess()) {
                    result.successCount += 1;
                    result.insertedIds.add(saveResult.getId());
                } else {
                    List<String> messages = new List<String>();
                    for (Database.Error databaseError : saveResult.getErrors()) {
                        messages.add(databaseError.getMessage());
                    }
                    result.errorsByIndex.put(inputIndex, String.join(messages, '; '));
                }
            }
        }

        return result;
    }

    private static String getNormalizedEmail(String email) {
        if (email == null) {
            return null;
        }

        String trimmedEmail = email.trim();
        if (trimmedEmail == '') {
            return null;
        }

        return trimmedEmail.toLowerCase();
    }
}
