    public static Integer publishShipments(List<ShipmentEventPublisher.Shipment> shipments) {
        if (shipments == null || shipments.isEmpty()) {
            return 0;
        }

        List<FB_Shipment_Event__e> events = new List<FB_Shipment_Event__e>();

        for (ShipmentEventPublisher.Shipment shipment : shipments) {
            if (shipment == null || String.isBlank(shipment.orderNumber)) {
                continue;
            }

            FB_Shipment_Event__e event = new FB_Shipment_Event__e();
            event.Order_Number__c = shipment.orderNumber;
            event.Tracking_Number__c = shipment.trackingNumber;
            event.Carrier__c = shipment.carrier;
            events.add(event);
        }

        if (events.isEmpty()) {
            return 0;
        }

        Map<FB_Shipment_Event__e, Boolean> publishResults = EventBus.publishAfterCommit(events);
        Integer publishedCount = 0;

        if (publishResults != null) {
            for (Boolean success : publishResults.values()) {
                if (success == true) {
                    publishedCount++;
                }
            }
        }

        return publishedCount;
    }
}
