public class AccountScoringJob implements Queueable {
    private List<Id> accountIds;
    private static final Integer BATCH_SIZE = 200;

    public AccountScoringJob() {
        this.accountIds = new List<Id>();
    }

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null) ? new List<Id>() : accountIds;
    }

    public void execute(System.QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer batchSize = accountIds.size() < BATCH_SIZE ? accountIds.size() : BATCH_SIZE;
        List<Id> batchIds = new List<Id>();

        for (Integer i = 0; i < batchSize; i++) {
            Id id = accountIds[i];
            if (id != null) {
                batchIds.add(id);
            }
        }

        if (!batchIds.isEmpty()) {
            Account[] accounts = [SELECT Id, AnnualRevenue FROM Account WHERE Id IN :batchIds];

            for (Account account : accounts) {
                if (account.AnnualRevenue != null && account.AnnualRevenue >= 1000000) {
                    account.Rating = 'Hot';
                } else if (account.AnnualRevenue != null && account.AnnualRevenue >= 100000) {
                    account.Rating = 'Warm';
                } else {
                    account.Rating = 'Cold';
                }
            }

            update accounts;
        }

        if (batchSize < accountIds.size()) {
            List<Id> remainingIds = new List<Id>();
            for (Integer i = batchSize; i < accountIds.size(); i++) {
                remainingIds.add(accountIds[i]);
            }

            System.enqueueJob(new AccountScoringJob(remainingIds));
        }
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }

        List<Id> snapshot = new List<Id>();
        for (Id id : accountIds) {
            snapshot.add(id);
        }

        return System.enqueueJob(new AccountScoringJob(snapshot));
    }
}
