public class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        Set<Id> accountIdsToQuery = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                accountIdsToQuery.add(accountId);
                result.put(accountId, 0);
            }
        }

        if (accountIdsToQuery.isEmpty()) {
            return result;
        }

        Integer currentYear = Date.today().year();
        Date startOfYear = Date.newInstance(currentYear, 1, 1);
        Date endOfYear = Date.newInstance(currentYear + 1, 1, 1);

        List<AggregateResult> aggregates = [
            SELECT AccountId, SUM(Amount) TotalAmount
            FROM Opportunity
            WHERE IsWon = true
                AND CloseDate >= :startOfYear
                AND CloseDate < :endOfYear
                AND AccountId IN :accountIdsToQuery
            GROUP BY AccountId
        ];

        for (AggregateResult aggregate : aggregates) {
            Id accountId = (Id) aggregate.get('AccountId');

            if (accountId == null || !result.containsKey(accountId)) {
                continue;
            }

            Decimal totalAmount = (Decimal) aggregate.get('TotalAmount');
            if (totalAmount == null) {
                totalAmount = 0;
            }

            result.put(accountId, totalAmount);
        }

        return result;
    }
}
