name: Salesforce Code Analyzer

on:
  pull_request:
    branches:
      - main

permissions:
  contents: read
  security-events: write

jobs:
  code-analyzer:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Install Salesforce CLI
        run: |
          sudo npm install -g @salesforce/cli
          sf --version

      - name: Run Salesforce Code Analyzer
        run: |
          set -euo pipefail
          mkdir -p reports
          sf code analyzer run \
            --target-dir force-app \
            --target-type source \
            --rule-set RECOMMENDED \
            --format sarif \
            --output reports/code-analyzer.sarif || true
          if [ ! -f reports/code-analyzer.sarif ]; then
            echo "SARIF output was not created."
            exit 1
          fi

      - name: Upload SARIF to GitHub code scanning
        if: always()
        uses: github/codeql-action/upload-sarif@v3
        with:
          sarif_file: reports/code-analyzer.sarif

      - name: Fail on High or Critical violations
        if: always()
        run: |
          set -euo pipefail
          node - <<'NODE'
          const fs = require('fs');
          const sarif = JSON.parse(fs.readFileSync('reports/code-analyzer.sarif', 'utf8'));
          const results = (sarif.runs || []).flatMap((run) => run.results || []);
          const getSeverity = (result) => {
            const candidates = [
              result.properties?.severity,
              result.properties?.rule?.severity,
              result.properties?.issue?.severity,
              result.severity
            ];
            for (const candidate of candidates) {
              if (typeof candidate === 'string' && candidate.trim()) {
                return candidate.trim().toLowerCase();
              }
              if (candidate && typeof candidate === 'object') {
                if (typeof candidate.name === 'string' && candidate.name.trim()) {
                  return candidate.name.trim().toLowerCase();
                }
                if (typeof candidate.value === 'string' && candidate.value.trim()) {
                  return candidate.value.trim().toLowerCase();
                }
              }
            }
            return '';
          };
          const hasSerious = results.some((result) => {
            const severity = getSeverity(result);
            if (severity) {
              return severity === 'critical' || severity === 'high';
            }
            return String(result.level || '').toLowerCase() === 'error';
          });
          if (hasSerious) {
            console.error('Salesforce Code Analyzer found one or more High or Critical violations.');
            process.exit(1);
          }
          console.log('No High or Critical Salesforce Code Analyzer violations found.');
          NODE
