public class Opportunities extends fflib_SObjectDomain {

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public Opportunities construct() {
            return new Opportunities();
        }
    }

    public virtual void onInsert(List<sObject> sobjs) {
        if (sobjs == null) {
            return;
        }

        for (sObject sobj : sobjs) {
            if (sobj == null) {
                continue;
            }

            Opportunity opp = (Opportunity) sobj;

            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    public virtual void onUpdate(List<sObject> sobjs) {
        if (sobjs == null) {
            return;
        }

        Map<Id, sObject> oldMap = Trigger.oldMap;

        for (sObject sobj : sobjs) {
            if (sobj == null) {
                continue;
            }

            Opportunity opp = (Opportunity) sobj;

            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }

            if (oldMap != null && opp.Id != null) {
                sObject oldSobj = oldMap.get(opp.Id);

                if (oldSobj != null) {
                    Opportunity oldOpp = (Opportunity) oldSobj;

                    if (oldOpp.StageName == 'Closed Won' && opp.Amount != oldOpp.Amount) {
                        error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
                    }
                }
            }
        }
    }
}
