public class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        List<Contact> fetchedContacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
            FOR UPDATE
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contact : fetchedContacts) {
            if (contact.Phone != null && contact.Phone != '') {
                String normalizedPhone = contact.Phone.replaceAll('[^0-9+]', '');

                if (normalizedPhone != '') {
                    contactsToUpdate.add(new Contact(Id = contact.Id, Phone = normalizedPhone));
                } else {
                    contactsToUpdate.add(new Contact(Id = contact.Id, Phone = null));
                }
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            List<Database.SaveResult> saveResults = Database.update(contactsToUpdate, false);

            for (Database.SaveResult saveResult : saveResults) {
                if (!saveResult.isSuccess() && !failures.containsKey(saveResult.getId())) {
                    String firstErrorMessage = 'Unknown save error';
                    List<Database.Error> errors = saveResult.getErrors();

                    if (errors != null && !errors.isEmpty()) {
                        String message = errors.get(0).getMessage();
                        if (message != null && message != '') {
                            firstErrorMessage = message;
                        }
                    }

                    failures.put(saveResult.getId(), firstErrorMessage);
                }
            }
        }

        return failures;
    }
}
