trigger OpportunityTrigger on Opportunity (after insert, after update, after delete) {
    // Collect the unique accounts affected in this transaction.
    // Instead of queuing one @future per opportunity, queue one @future per
    // transaction/chunk so 200-record CPQ batches stay within future-call limits.
    // This also recalculates on account reassignment and deletion.
    Set<Id> accountIds = new Set<Id>();

    if (Trigger.isInsert) {
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    }

    if (Trigger.isUpdate) {
        for (Integer i = 0; i < Trigger.new.size(); i++) {
            Opportunity newOpp = Trigger.new[i];
            Opportunity oldOpp = Trigger.old[i];

            if (newOpp.AccountId != oldOpp.AccountId) {
                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
                if (newOpp.AccountId != null) {
                    accountIds.add(newOpp.AccountId);
                }
            } else if (newOpp.StageName != oldOpp.StageName || newOpp.Amount != oldOpp.Amount) {
                if (newOpp.AccountId != null) {
                    accountIds.add(newOpp.AccountId);
                }
            }
        }
    }

    if (Trigger.isDelete) {
        for (Opportunity opp : Trigger.old) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    }

    if (!accountIds.isEmpty()) {
        List<Id> ids = new List<Id>(accountIds);

        for (Integer start = 0; start < ids.size(); start += 1000) {
            Integer end = Math.min(start + 1000, ids.size());
            List<Opportunity> affected = new List<Opportunity>();

            for (Integer i = start; i < end; i++) {
                affected.add(new Opportunity(AccountId = ids[i]));
            }

            AccountRatingService.recalculate(affected);
        }
    }
}
