public with sharing class AccountRatingService {
    private static final String RATING_HOT = 'Hot';
    private static final String RATING_WARM = 'Warm';
    private static final String RATING_COLD = 'Cold';
    private static final Integer SOQL_CHUNK_SIZE = 200;

    @future
    public static void recalculate(List<Opportunity> opportunities) {
        Set<Id> accountIds = new Set<Id>();

        if (opportunities != null) {
            for (Opportunity opp : opportunities) {
                if (opp != null && opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
            }
        }

        recalculateAccountRatings(accountIds);
    }

    private static void recalculateAccountRatings(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        List<Id> ids = new List<Id>(accountIds);
        List<Account> accountsToUpdate = new List<Account>();
        Map<Id, Account> accountsToUpdateMap = new Map<Id, Account>();

        for (Integer start = 0; start < ids.size(); start += SOQL_CHUNK_SIZE) {
            Integer end = Math.min(start + SOQL_CHUNK_SIZE, ids.size());
            List<Id> chunk = ids.sublist(start, end);

            Map<Id, AggregateResult> oppSummaryByAccount = new Map<Id, AggregateResult>();

            for (AggregateResult result : [
                SELECT AccountId,
                       SUM(CASE WHEN Amount != null AND Amount >= 100000 THEN 1 ELSE 0 END) hotCount
                FROM Opportunity
                WHERE AccountId IN :chunk
                AND IsClosed = false
                GROUP BY AccountId
            ]) {
                oppSummaryByAccount.put((Id) result.get('AccountId'), result);
            }

            Map<Id, Account> accountsById = new Map<Id, Account>([
                SELECT Id, Rating
                FROM Account
                WHERE Id IN :chunk
            ]);

            for (Id accountId : chunk) {
                Account account = accountsById.get(accountId);

                if (account == null) {
                    continue;
                }

                String rating;

                if (oppSummaryByAccount.containsKey(accountId)) {
                    Decimal hotCount = (Decimal) oppSummaryByAccount.get(accountId).get('hotCount');

                    if (hotCount != null && hotCount > 0) {
                        rating = RATING_HOT;
                    } else {
                        rating = RATING_WARM;
                    }
                } else {
                    rating = RATING_COLD;
                }

                if (account.Rating != rating && !accountsToUpdateMap.containsKey(accountId)) {
                    account.Rating = rating;
                    accountsToUpdateMap.put(accountId, account);
                    accountsToUpdate.add(account);
                }
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
