public class RenewalReminderService {
    // Note: 200 per call is a bad production choice because Apex is limited to 100
    // email messages per transaction (and SOQL IN lists are limited). This method
    // chunks the query and stops attempting sends if the email limit is reached.
    private static final Integer QUERY_CHUNK_SIZE = 100;

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.size() == 0) {
            return 0;
        }

        Set<Id> uniqueIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                uniqueIds.add(opportunityId);
            }
        }

        if (uniqueIds.size() == 0) {
            return 0;
        }

        List<Id> uniqueIdList = new List<Id>();
        for (Id opportunityId : uniqueIds) {
            uniqueIdList.add(opportunityId);
        }

        List<Opportunity> opportunities = new List<Opportunity>();
        for (Integer start = 0; start < uniqueIdList.size(); start += QUERY_CHUNK_SIZE) {
            Integer end = (start + QUERY_CHUNK_SIZE < uniqueIdList.size()) ? (start + QUERY_CHUNK_SIZE) : uniqueIdList.size();
            List<Id> chunk = new List<Id>();
            for (Integer i = start; i < end; i++) {
                chunk.add(uniqueIdList[i]);
            }

            opportunities.addAll([
                SELECT Id,
                       Name,
                       CloseDate,
                       OwnerId
                FROM Opportunity
                WHERE Id IN :chunk
            ]);
        }

        Integer sentCount = 0;

        for (Opportunity opportunity : opportunities) {
            if (opportunity.OwnerId == null) {
                continue;
            }

            try {
                Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
                email.setTargetObjectId(opportunity.OwnerId);
                email.setSaveAsActivity(false);

                String opportunityName = opportunity.Name == null ? '' : opportunity.Name;
                email.setSubject('Renewal due: ' + opportunityName);

                String closeDateText = opportunity.CloseDate == null ? 'not set' : String.valueOf(opportunity.CloseDate);
                email.setPlainTextBody('Close date: ' + closeDateText);

                Messaging.SendEmailResult[] results = Messaging.sendEmail(
                    new List<Messaging.SingleEmailMessage>{ email }
                );

                if (results != null && results.size() > 0 && results[0].isSuccess()) {
                    sentCount++;
                }
            } catch (LimitException e) {
                break;
            } catch (Exception e) {
                // Continue with the next opportunity.
            }
        }

        return sentCount;
    }
}
