        this.generateCaseListUrl();
    }

    handleAction(event) {
        const action = event.currentTarget.dataset.action;

        if (action === 'new-contact') {
            this.openNewContact();
        } else if (action === 'contacts') {
            this.openContacts();
        } else if (action === 'edit') {
            this.openEdit();
        }
    }

    openNewContact() {
        if (!this.recordId) {
            return;
        }

        this.runGenerateUrl({
            recordObjectType: 'Contact',
            actionName: 'new',
            state: {
                defaultFieldValues: encodeDefaultFieldValues({
                    AccountId: this.recordId
                })
            }
        })
            .then((pageRef) => this.runNavigate(pageRef))
            .catch((error) => {
                console.error('Failed to open New Contact page', error);
            });
    }

    openContacts() {
        if (!this.recordId) {
            return;
        }

        this.runGenerateUrl({
            recordObjectType: 'Account',
            recordId: this.recordId,
            actionName: 'view',
            state: {
                relationshipName: 'Contacts'
            }
        })
            .then((pageRef) => this.runNavigate(pageRef))
            .catch((error) => {
                console.error('Failed to open Contacts list', error);
            });
    }

    openEdit() {
        if (!this.recordId) {
            return;
        }

        this.runGenerateUrl({
            recordObjectType: 'Account',
            recordId: this.recordId,
            actionName: 'edit'
        })
            .then((pageRef) => this.runNavigate(pageRef))
            .catch((error) => {
                console.error('Failed to open Edit Account page', error);
            });
    }

    generateCaseListUrl() {
        this.runGenerateUrl({
            recordObjectType: 'Case',
            actionName: 'list',
            state: {
                filterName: 'My_Open_Cases'
            }
        })
            .then((pageRef) => {
                if (pageRef && pageRef.url) {
                    this.casesUrl = pageRef.url;
                }
            })
            .catch((error) => {
                console.error('Failed to generate Case list URL', error);
            });
    }

    runGenerateUrl(config) {
        const generateUrl =
            this.generateUrl ||
            this[NavigationMixin.GenerateUrl] ||
            NavigationMixin.GenerateUrl;

        if (typeof generateUrl !== 'function') {
            return Promise.reject(new Error('NavigationMixin.GenerateUrl is not available.'));
        }

        return Promise.resolve(generateUrl.call(this, config));
    }

    runNavigate(pageRef) {
        const navigate =
            this.navigate ||
            this[NavigationMixin.Navigate] ||
            NavigationMixin.Navigate;

        if (typeof navigate !== 'function' || !pageRef) {
            return Promise.reject(new Error('NavigationMixin.Navigate is not available.'));
        }

        return Promise.resolve(navigate.call(this, pageRef));
    }
}
