import { LightningElement, api, track } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import LightningConfirm from 'lightning/confirm';
import { ShowToastEvent } from 'lightning/platformMessageShowToastEvent';

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    _opportunities = [];

    @track displayOpportunities = [];

    @api get opportunities() {
        return this._opportunities;
    }

    @api set opportunities(value) {
        this._opportunities = value;
        this.displayOpportunities = Array.isArray(value) ? value : [];
    }

    get data() {
        return this.displayOpportunities;
    }

    get columns() {
        return [
            { label: 'Name', fieldName: 'Name' },
            { label: 'Stage', fieldName: 'StageName' },
            { label: 'Amount', fieldName: 'Amount', type: 'currency' },
            {
                type: 'action',
                typeAttributes: {
                    rowActions: [
                        { label: 'View', name: 'view' },
                        { label: 'Edit', name: 'edit' },
                        { label: 'Delete', name: 'delete' }
                    ]
                }
            }
        ];
    }

    handleRowAction(event) {
        const action = event.detail.action;
        const row = event.detail.row;

        if (!action || !row) {
            return;
        }

        if (action.name === 'view') {
            this.navigateToRecord(row.Id, 'view');
        } else if (action.name === 'edit') {
            this.navigateToRecord(row.Id, 'edit');
        } else if (action.name === 'delete') {
            this.deleteOpportunity(row);
        }
    }

    navigateToRecord(recordId, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId,
                actionName
            }
        });
    }

    deleteOpportunity(row) {
        LightningConfirm.open({
            label: 'Delete Opportunity',
            message: `Are you sure you want to delete ${row.Name}?`,
            confirmLabel: 'Delete',
            cancelLabel: 'Cancel'
        })
            .then((confirmed) => {
                if (!confirmed) {
                    return;
                }

                deleteRecord(row.Id)
                    .then(() => {
                        const current = this.displayOpportunities;

                        this.displayOpportunities = current.filter(
                            (record) => record.Id !== row.Id
                        );

                        this.dispatchEvent(
                            new ShowToastEvent({
                                variant: 'success',
                                title: 'Opportunity deleted'
                            })
                        );
                    })
                    .catch((error) => {
                        let message;
                        if (error && error.body) {
                            message = error.body.message;
                        }

                        this.dispatchEvent(
                            new ShowToastEvent({
                                variant: 'error',
                                title: 'Delete failed',
                                message
                            })
                        );
                    });
            })
            .catch(() => {
                // Do nothing if the confirm dialog cannot be opened.
            });
    }
}
