public class EmployerService {
    /**
     * Sets the current employer for the supplied contacts by using NPSP's
     * standard primary-affiliation mechanism:
     * Contact.npsp__Primary_Affiliation__c.
     *
     * NPSP maintains the Affiliation records when this field changes, including
     * demoting the previous primary affiliation to Former with an end date of
     * today.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>();
        Map<String, Id> employerByNormalizedContactId = new Map<String, Id>();

        for (Id contactId : employerByContactId.keySet()) {
            Id employerId = employerByContactId.get(contactId);

            if (contactId != null && employerId != null) {
                contactIds.add(contactId);
                employerByNormalizedContactId.put(normalizeId(contactId), employerId);
            }
        }

        if (contactIds.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contact : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            Id employerId = employerByNormalizedContactId.get(normalizeId(contact.Id));
            if (employerId == null) {
                continue;
            }

            // If the organization is already the primary affiliation, do nothing.
            if (!sameId(contact.npsp__Primary_Affiliation__c, employerId)) {
                contact.npsp__Primary_Affiliation__c = employerId;
                contactsToUpdate.add(contact);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }

    private static Boolean sameId(Id first, Id second) {
        if (first == null && second == null) {
            return true;
        }

        if (first == null || second == null) {
            return false;
        }

        return normalizeId(first) == normalizeId(second);
    }

    private static String normalizeId(Id id) {
        String value = String.valueOf(id);

        if (value.length() == 18) {
            value = value.substring(0, 15);
        }

        return value.toLowerCase();
    }
}
