public with sharing class PaymentPlanService {
    public class PaymentPlanException extends Exception {
        public PaymentPlanException() {
            super();
        }

        public PaymentPlanException(String message) {
            super(message);
        }
    }

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be greater than or equal to 1.');
        }

        if (opportunityId == null) {
            throw new PaymentPlanException('Opportunity Id is required.');
        }

        if (firstPaymentDate == null) {
            throw new PaymentPlanException('First payment date is required.');
        }

        Opportunity opportunity;
        try {
            opportunity = [
                SELECT Id, Amount, IsClosed
                FROM Opportunity
                WHERE Id = :opportunityId
                LIMIT 1
            ];
        } catch (Exception e) {
            throw new PaymentPlanException('Unable to load opportunity: ' + e.getMessage());
        }

        if (opportunity == null) {
            throw new PaymentPlanException('Opportunity was not found or is not accessible.');
        }

        if (opportunity.IsClosed == true) {
            throw new PaymentPlanException('Only open opportunities can be converted to an installment plan.');
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT
                Id,
                npe01__Payment_Amount__c,
                npe01__Paid__c,
                npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        Decimal paidOrWrittenOffTotal = 0;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c payment : existingPayments) {
            if (payment.npe01__Paid__c == true || payment.npe01__Written_Off__c == true) {
                if (payment.npe01__Payment_Amount__c != null) {
                    paidOrWrittenOffTotal += payment.npe01__Payment_Amount__c;
                }
            } else {
                paymentsToDelete.add(payment);
            }
        }

        Decimal opportunityAmount = opportunity.Amount == null ? 0 : opportunity.Amount;
        Decimal outstandingAmount = opportunityAmount - paidOrWrittenOffTotal;

        if (outstandingAmount <= 0) {
            throw new PaymentPlanException('Outstanding amount is not greater than zero.');
        }

        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }

        Decimal installmentAmount = outstandingAmount.divide(
            (Decimal)numberOfPayments,
            2,
            System.RoundingMode.DOWN
        );

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amount;

            if (i == numberOfPayments - 1) {
                amount = outstandingAmount - (installmentAmount * (numberOfPayments - 1));
            } else {
                amount = installmentAmount;
            }

            newPayments.add(
                new npe01__OppPayment__c(
                    npe01__Opportunity__c = opportunityId,
                    npe01__Payment_Amount__c = amount,
                    npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                    npe01__Paid__c = false,
                    npe01__Written_Off__c = false
                )
            );
        }

        insert newPayments;

        return newPayments;
    }
}
