public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {
    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final Decimal MIN_MAJOR_GIFT_AMOUNT = 5000;
    private static final Integer ACTIVITY_OFFSET_DAYS = 3;

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        List<Task> tasksToInsert = new List<Task>();

        if (newlist == null || newlist.isEmpty()) {
            return null;
        }

        if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
            for (SObject record : newlist) {
                Opportunity opportunity = (Opportunity) record;
                if (isMajorGift(opportunity)) {
                    tasksToInsert.add(buildTask(opportunity));
                }
            }
        } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
            Map<Id, Opportunity> oldOpportunities = new Map<Id, Opportunity>();
            if (oldlist != null) {
                for (SObject record : oldlist) {
                    Opportunity oldOpportunity = (Opportunity) record;
                    if (oldOpportunity != null && oldOpportunity.Id != null) {
                        oldOpportunities.put(oldOpportunity.Id, oldOpportunity);
                    }
                }
            }

            for (SObject record : newlist) {
                Opportunity opportunity = (Opportunity) record;
                if (!isMajorGift(opportunity)) {
                    continue;
                }

                Opportunity oldOpportunity = oldOpportunities.get(opportunity.Id);
                if (oldOpportunity == null || !isMajorGift(oldOpportunity)) {
                    tasksToInsert.add(buildTask(opportunity));
                }
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return null;
    }

    private static Boolean isMajorGift(Opportunity opportunity) {
        return opportunity != null
            && opportunity.StageName != null
            && opportunity.StageName.equals(STAGE_CLOSED_WON)
            && opportunity.Amount != null
            && opportunity.Amount >= MIN_MAJOR_GIFT_AMOUNT;
    }

    private static Task buildTask(Opportunity opportunity) {
        Task task = new Task(
            Subject = 'Major gift thank-you call',
            Priority = 'High',
            Status = 'Not Started',
            WhatId = opportunity.Id,
            WhoId = opportunity.npsp__Primary_Contact__c,
            OwnerId = opportunity.OwnerId,
            ActivityDate = opportunity.CloseDate == null ? null : opportunity.CloseDate.addDays(ACTIVITY_OFFSET_DAYS)
        );

        return task;
    }
}
