public with sharing class EmployeeDirectoryService {
    private static final String OBJECT_API_NAME = 'FB_Employee__c';
    private static final List<String> DISPLAY_FIELDS = new List<String>{
        'Name',
        'Department__c',
        'Salary__c',
        'Personal_Email__c'
    };

    public static List<FB_Employee__c> getDirectory() {
        List<FB_Employee__c> employees = new List<FB_Employee__c>();

        Schema.SObjectType objectType = Schema.getGlobalDescribe().get(OBJECT_API_NAME);
        if (objectType == null || !objectType.getDescribe().isViewable()) {
            return employees;
        }

        List<String> fieldsToQuery = new List<String>{ 'Id' };
        Map<String, Schema.SObjectField> fieldMap = objectType.getFieldMap();

        for (String fieldName : DISPLAY_FIELDS) {
            Schema.SObjectField field = fieldMap.get(fieldName);
            if (field != null && field.getDescribe().isAccessible()) {
                fieldsToQuery.add(fieldName);
            }
        }

        String soql = 'SELECT ' + String.join(fieldsToQuery, ', ') + ' FROM ' + OBJECT_API_NAME + ' ORDER BY Name ASC';

        for (SObject record : Database.query(soql)) {
            employees.add((FB_Employee__c) record);
        }

        return employees;
    }
}
