public with sharing class AccountOwnershipService {
    private static final String ACCOUNT_SOBJECT_NAME = 'Account';

    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        Set<Id> validAccountIds = new Set<Id>();
        if (accountIds != null) {
            for (Id accountId : accountIds) {
                if (accountId != null) {
                    validAccountIds.add(accountId);
                }
            }
        }

        if (validAccountIds.isEmpty()) {
            return;
        }

        try {
            TriggerBase.bypass(ACCOUNT_SOBJECT_NAME);

            List<Account> accounts = [
                SELECT Id, OwnerId
                FROM Account
                WHERE Id IN :validAccountIds
            ];

            for (Account account : accounts) {
                account.OwnerId = newOwnerId;
            }

            List<Contact> contacts = [
                SELECT Id, OwnerId, AccountId
                FROM Contact
                WHERE AccountId IN :validAccountIds
            ];

            for (Contact contact : contacts) {
                contact.OwnerId = newOwnerId;
            }

            if (accounts.isEmpty() && contacts.isEmpty()) {
                return;
            }

            SavePoint savePoint = System.setSavepoint();
            try {
                if (!accounts.isEmpty()) {
                    update accounts;
                }
                if (!contacts.isEmpty()) {
                    update contacts;
                }
            } catch (Exception e) {
                try {
                    System.rollback(savePoint);
                } catch (Exception rollbackException) {
                    // Preserve the original DML exception.
                    throw e;
                }
                throw e;
            }
        } finally {
            TriggerBase.clearBypass(ACCOUNT_SOBJECT_NAME);
        }
    }
}
